function sortJsonByKeys(json) {
  const sortedKeys = Object.keys(json).sort((a, b) => a.localeCompare(b));
  return sortedKeys.reduce((accumulator, currentKey) => {
    accumulator[currentKey] = json[currentKey];
    return accumulator;
  }, {});
}

const jsonObject = {
  apple: 3,
  banana: 2,
  cherry: 1
};

const sortedJsonObject = sortJsonByKeys(jsonObject);
console.log(sortedJsonObject); // Output: {apple: 3, banana: 2, cherry: 1}
```

This function first sorts the keys of the JSON object using the `Array.prototype.sort()` method with a custom compare function that compares the keys using the `localeCompare()` method. Then, it iterates through the sorted keys and adds each key-value pair to a new object using the `Reduce()` method. Finally, it returns the sorted object.

