Here's a Go program that parses a struct in a Go source file and generates an Avro schema from it:

```go
package main

import (
	"fmt"
	"io/ioutil"
	"regexp"
	"strings"

	"github.com/apache/avro/avro"
)

func main() {
	filePath := "path/to/your/go/source/file.go"
	structName := "YourStructName"

	content, err := ioutil.ReadFile(filePath)
	if err != nil {
		fmt.Println("Error reading file:", err)
		return
	}

	// Regular expression pattern to match struct definition
	pattern := `type (?P<struct_name>\w+)\{`

	// Match struct definition in the source code
	match := regexp.MustCompile(pattern).FindStringSubmatch(string(content))
	if len(match) == 0 {
		fmt.Println("Error finding struct definition in the source code.")
		return
	}

	// Extract struct fields and their types
	fields := []avro.Field{}
	for _, line := range strings.Split(match[1], "\n") {
		parts := strings.Split(line, " ")
		if len(parts) >= 2 {
			fieldName := parts[0]
			fieldType := parts[1]
			fields = append(fields, avro.Field{Name: fieldName, Type: avro.Type(fieldType)})
		}
	}

	// Generate Avro schema
	schema, err := avro.NewSchema(structName, fields)
	if err != nil {
		fmt.Println("Error generating Avro schema:", err)
		return
	}

	// Save Avro schema to a file
	err = ioutil.WriteFile("struct.avsc", schema.ToString(), 0644)
	if err != nil {
		fmt.Println("Error writing Avro schema to file:", err)
		return
	}

	fmt

Here's an HTML page that displays the background image of the user's computer on the desktop when the "Display Background Image" button is clicked:

```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Display Background Image</title>
    <style>
        body {
            text-align: center;
            margin-top: 50%;
        }
        button {
            background-color: #4CAF50;
            color: white;
            padding: 10px 20px;
            border: none;
            cursor: pointer;
        }
        button:hover {
            background-color: #45a049;
        }
    </style>
</head>
<body>
    <h1>Display Background Image</h1>
    <button onclick="displayBackgroundImage()">Click me to display background image</button>
    <script>
        function displayBackgroundImage() {
            chrome.tabs.query({active: true, currentWindow: true}, tabs => {
                chrome.tabs.executeScript(tabs[0].id, {file: 'background_image_script.js'});
            });
        }
    </script>
</body>
</html>
```

Create a new file named `background_image_script.js` in the same directory as the HTML file and add the following code:

```javascript
chrome.runtime.sendMessage({action: 'getBackgroundImage'}, function(response) {
    if (response.imageUrl) {
        const backgroundImage = document.createElement('img');
        backgroundImage.src = response.imageUrl;
        backgroundImage.style.position = 'absolute';
        backgroundImage.style.top = '0';
        backgroundImage.style.left = '0';
        backgroundImage.style.width = '100%';
        backgroundImage.style.height = '100%';
        document.body.appendChild(backgroundImage);
    }
});
``

