Here's a custom decorator for Nest.js middleware that checks the NODE_ENV variable and returns `false` if it's not equal to 'true'. Otherwise, it calls the next middleware function.

```typescript
import { createParamDecorator, ExecutionContext } from '@nestjs/common';

export const IsDevModeEnabled = createParamDecorator(
  (data: unknown, ctx: ExecutionContext) => {
    const request = ctx.switchToHttp().getRequest();
    const nodeEnv = request.nodeEnv;

    return nodeEnv === 'true';
  },
);

export function DevModeMiddleware(middleware: any[]) {
  return async (req, res, next) => {
    if (!IsDevModeEnabled()) {
      return res.status(403).json({ error: 'Development mode is disabled.' });
    }

    await Promise.all(middleware.map((m) => m(req, res, next)));
  };
}
```

Now you can use this decorator in your controllers like this:

```typescript
import { Controller, Get, UseInterceptors, ClassSerializerInterceptor } from '@nestjs/common';
import { DevModeMiddleware } from './dev-mode.middleware';

@Controller('api')
export class MyController {
  @Get()
  @UseInterceptors(ClassSerializerInterceptor)
  @DevModeMiddleware([
    // Add your middlewares here
  ])
  getData() {
    // Your logic here
  }
}
```

