Here's an example of how you can program an email input field using TypeScript, React with the Downshift library's `useCombobox` component. This input field will autocomplete the email as the user types by calling the `searchEmails` function from the Downshift library.

```tsx
import { useCombobox } from 'downshift';
import { useState } from 'react';
import axios from 'axios';

interface Email {
  id: number;
  email: string;
}

const EmailInput: React.FC = () => {
  const [emails, setEmails] = useState([]);
  const [query, setQuery] = useState('');

  const fetchEmails = async (prefix: string) => {
    try {
      const response = await axios.get(`https://example.com/api/emails?q=${prefix}`);
      setEmails(response.data);
    } catch (error) {
      console.error(error);
    }
  };

  const { isOpen, selectedItem, getMenuProps, getInputProps, getComboboxProps } = useCombobox({
    items: emails,
    getItemToString: (item) => item.email,
    onSelect: (selectedItem) => {
      setQuery(selectedItem.email);
    },
    onInputValueChange: (inputValue) => {
      setQuery(inputValue);
      fetchEmails(inputValue);
    },
  });

  return (
    <div {...getComboboxProps()}>
      <input {...getInputProps()} placeholder="Search emails" value={query} onChange={(e) => setQuery(e.target.value)} />
      <div {...getMenuProps()}>
        {isOpen && (
          <ul>
            {emails.map((email) => (
              <li key={email.id}>{email.email}</li>
            ))}
          </ul>
        )}
      </div>
    </div>
  );
};

export default EmailInput;
```

