```javascript
const { Redis } = require("ioredis");

class RedisClient {
  constructor() {
    this.client = new Redis({
      host: "localhost",
      port: 6379,
      password: null, // Add your Redis password if necessary
    });

    this.client.on("error", (err) => {
      console.error("Error connecting to Redis:", err);
    });
  }

  async isAlive() {
    try {
      await this.client.ping();
      return true;
    } catch (err) {
      console.error("Error checking Redis connection:", err);
      return false;
    }
  }

  async get(key) {
    try {
      const value = await this.client.get(key);
      return value;
    } catch (err) {
      console.error("Error retrieving value from Redis:", err);
      throw err;
    }
  }

  async set(key, value, duration) {
    try {
      await this.client.setex(key, duration, value);
    } catch (err) {
      console.error("Error setting value in Redis:", err);
      throw err;
    }
  }

  async del(key) {
    try {
      await this.client.del(key);
    } catch (err) {
      console.error("Error deleting value in Redis:", err);
      throw err;
    }
  }
}

const redisClient = new RedisClient();

module.exports = redisClient;
```

This code defines the `RedisClient` class and exports an instance of it called `redisClient`. The class provides methods to check the connection to Redis, retrieve values, set values with an expiration, and delete values. It also handles errors and logs them to the console.

